service.method:

		   UPDATE SNOTD snotd
			  SET snotd.DEL_FLAG = 'Y'
			WHERE snotd.NOTICE_NUMBER = ${NOTICE_NUMBER}
			  AND EXISTS (
    						SELECT 1
    						  FROM SNOTE snote
    						 WHERE snotd.NOTICE_NUMBER = snote.NOTICE_NUMBER
    						   AND snote.COMPANY_CODE = '${COMPANY_CODE}
						)


UPDATE SNOTE
   SET VIEW_COUNT    = VIEW_COUNT+1
 WHERE NOTICE_NUMBER = ${NOTICE_NUMBER}
